"""ARC task IO and the deterministic local ARC-AGI-2-format benchmark pack.

Task format (identical to the official ARC-AGI-2 JSONL):
    {"id": str, "train": [{"input": [[int]], "output": [[int]]}],
     "test":  [{"input": [[int]], "output": [[int]]}]}

The pack is generated locally (no download). On Kaggle, point --data at the
official `arc-agi-2-data` dataset directory and the same loader is used.
"""
from __future__ import annotations

import json
import os
import random
from typing import Dict, Iterable, List, Tuple

Grid = List[List[int]]
Task = Dict

OFFICIAL_CANDIDATES = [
    "data/ARC-AGI-2",
    "/kaggle/input/arc-agi-2-data/ARC-AGI-2",
    "/kaggle/input/arc-prize-2026",
]


# --------------------------------------------------------------------------- #
# Loading official / local JSONL
# --------------------------------------------------------------------------- #
def _read_jsonl(path: str) -> List[Task]:
    with open(path, "r", encoding="utf-8") as fh:
        return [json.loads(line) for line in fh if line.strip()]


def _try_official(data_dir: str | None) -> Dict[str, List[Task]] | None:
    candidates = [data_dir] if data_dir else []
    candidates += OFFICIAL_CANDIDATES
    for base in candidates:
        if not base:
            continue
        for split in ("training", "evaluation"):
            fname = f"{split}.jsonl"
            path = os.path.join(base, fname)
            if os.path.exists(path):
                train_path = os.path.join(base, "training.jsonl")
                eval_path = os.path.join(base, "evaluation.jsonl")
                return {
                    "training": _read_jsonl(train_path),
                    "evaluation": _read_jsonl(eval_path),
                }
            if os.path.exists(os.path.join(base, fname + ".zip")):
                raise FileNotFoundError(
                    f"Found {fname}.zip; unzip it first: cd {base} && unzip '*.zip'"
                )
    return None


def load_benchmark(data_dir: str | None = None) -> Dict[str, List[Task]]:
    """Load official ARC-AGI-2 JSONL if available, else the local generated pack."""
    official = _try_official(data_dir)
    if official is not None:
        return official
    return {"training": generate_pack(200, 1234),
            "evaluation": generate_pack(200, 5678)}


# --------------------------------------------------------------------------- #
# Deterministic synthetic ARC-AGI-2-format pack
# --------------------------------------------------------------------------- #
def _grid(h: int, w: int, fill: int = 0, rng: random.Random | None = None,
          noise: float = 0.0) -> Grid:
    g = [[fill for _ in range(w)] for _ in range(h)]
    if rng is not None and noise:
        for r in range(h):
            for c in range(w):
                if rng.random() < noise:
                    g[r][c] = rng.randint(0, 9)
    return g


def _paint(g: Grid, r0: int, c0: int, h: int, w: int, color: int) -> None:
    for r in range(r0, min(r0 + h, len(g))):
        for c in range(c0, min(c0 + w, len(g[0]))):
            g[r][c] = color


def gen_recolor(rng: random.Random) -> Task:
    h, w = rng.randint(5, 12), rng.randint(5, 12)
    a, b = rng.sample(range(1, 10), 2)
    pair = []
    for _ in range(4):
        g = _grid(h, w, 0, rng, noise=0.5)
        pair.append((g, [[a if x == b else x for x in row] for row in g]))
    return _pack("recolor", rng, pair)


def gen_fill_enclosed(rng: random.Random) -> Task:
    h, w = rng.randint(7, 12), rng.randint(7, 12)
    wall = rng.randint(1, 9)
    fill = rng.choice([c for c in range(1, 10) if c != wall])

    def make(seed_offset: int):
        r = random.Random(rng.randrange(1 << 30) ^ seed_offset)
        g = _grid(h, w, 0)
        rh, rw = r.randint(3, 4), rng.randint(3, 5)
        r0, c0 = r.randint(1, h - rh - 1), r.randint(1, w - rw - 1)
        for c in range(c0, c0 + rw):
            g[r0][c] = wall
            g[r0 + rh - 1][c] = wall
        for rr in range(r0, r0 + rh):
            g[rr][c0] = wall
            g[rr][c0 + rw - 1] = wall
        gap = r.randint(0, 3)
        if gap == 0:
            g[r0][c0 + rw // 2] = 0
        for rr in range(r0 + 1, r0 + rh - 1):
            for cc in range(c0 + 1, c0 + rw - 1):
                g[rr][cc] = fill
        return g

    pair = []
    for i in range(4):
        g = make(i)
        out = [row[:] for row in g]
        enclosed = _enclosed_mask(g)
        for rr in range(h):
            for cc in range(w):
                if enclosed[rr][cc] and g[rr][cc] == 0:
                    out[rr][cc] = fill
        pair.append((g, out))
    return _pack("fill", rng, pair)


def _enclosed_mask(g: Grid) -> List[List[bool]]:
    h, w = len(g), len(g[0])
    reach = [[False] * w for _ in range(h)]
    stack = []
    for r in range(h):
        for c in (0, w - 1):
            if g[r][c] == 0:
                stack.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if g[r][c] == 0:
                stack.append((r, c))
    while stack:
        r, c = stack.pop()
        if not (0 <= r < h and 0 <= c < w) or reach[r][c] or g[r][c] != 0:
            continue
        reach[r][c] = True
        stack += [(r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)]
    return [[g[r][c] == 0 and not reach[r][c] for c in range(w)] for r in range(h)]


def gen_rotate(rng: random.Random) -> Task:
    h, w = rng.randint(5, 11), rng.randint(5, 11)
    pair = []
    for _ in range(4):
        g = _grid(h, w, 0, rng, noise=0.55)
        pair.append((g, [list(row) for row in zip(*g[::-1])]))
    return _pack("rot90", rng, pair)


def gen_flip(rng: random.Random) -> Task:
    axis = rng.choice(["h", "v"])
    h, w = rng.randint(5, 12), rng.randint(5, 12)
    pair = []
    for _ in range(4):
        g = _grid(h, w, 0, rng, noise=0.55)
        out = g[::-1] if axis == "h" else [row[::-1] for row in g]
        pair.append((g, [row[:] for row in out]))
    return _pack("flip" + axis, rng, pair)


def gen_gravity(rng: random.Random) -> Task:
    h, w = rng.randint(7, 12), rng.randint(5, 10)
    color = rng.randint(1, 9)

    def make():
        g = _grid(h, w, 0)
        n = rng.randint(4, h * w // 3)
        cells = rng.sample([(r, c) for r in range(h - 1) for c in range(w)], n)
        for r, c in cells:
            g[r][c] = color
        out = [row[:] for row in g]
        for c in range(w):
            k = sum(1 for r in range(h - 1) if g[r][c] == color)
            for r in range(h):
                out[r][c] = 0
            for r in range(h - 2, h - 2 - k, -1):
                out[r][c] = color
        g[h - 1] = [color] * w
        out[h - 1] = [color] * w
        return g, out

    pair = [make() for _ in range(4)]
    return _pack("gravity", rng, pair)


def gen_remove_noise(rng: random.Random) -> Task:
    h, w = rng.randint(7, 13), rng.randint(7, 13)
    color = rng.randint(1, 9)
    noise_colors = [c for c in range(1, 10) if c != color]

    def make():
        g = _grid(h, w, 0)
        s = rng.randint(3, 5)
        r0, c0 = rng.randint(0, h - s), rng.randint(0, w - s)
        _paint(g, r0, c0, s, s, color)
        g[r0 + s // 2][c0 + s // 2] = 0
        for _ in range(rng.randint(3, 8)):
            r, c = rng.randrange(h), rng.randrange(w)
            if g[r][c] == 0:
                g[r][c] = rng.choice(noise_colors)
        out = [[x if x == color else 0 for x in row] for row in g]
        return g, out

    pair = [make() for _ in range(4)]
    return _pack("denoise", rng, pair)


def gen_complete_symmetry(rng: random.Random) -> Task:
    h = w = rng.randint(7, 12)
    pair = []
    for _ in range(4):
        g = _grid(h, w, 0, rng, noise=0.25)
        for r in range(h):
            for c in range(w // 2):
                g[r][w - 1 - c] = g[r][c]
        out = [row[:] for row in g]
        for r in range(h):
            for c in range(w // 2):
                if rng.random() < 0.4:
                    out[r][w - 1 - c] = 0
        g2 = [row[:] for row in out]
        for r in range(h):
            for c in range(w // 2):
                g2[r][w - 1 - c] = out[r][c]
        pair.append((out, g2))
    return _pack("sym", rng, pair)


def gen_count_bars(rng: random.Random) -> Task:
    h, w = rng.randint(7, 11), rng.randint(7, 11)
    color = rng.randint(1, 9)

    def make():
        g = _grid(h, w, 0)
        col = rng.randrange(1, w - 1)
        n = rng.randint(1, h - 2)
        for r in range(h - 1 - n, h - 1):
            g[r][col] = color
        out = [row[:] for row in g]
        for r in range(h - 1):
            out[r][0] = color if r >= h - 1 - n else 0
        return g, out

    return _pack("count", rng, [make() for _ in range(4)])


def gen_tile(rng: random.Random) -> Task:
    th, tw = rng.randint(2, 3), rng.randint(2, 3)
    h, w = th * rng.randint(2, 3), tw * rng.randint(2, 3)
    motif = _grid(th, tw, 0, rng, noise=0.8)
    pair = []
    for _ in range(4):
        g = [[motif[r % th][c % tw] if rng.random() > 0.35 else 0
              for c in range(w)] for r in range(h)]
        out = [[motif[r % th][c % tw] for c in range(w)] for r in range(h)]
        pair.append((g, out))
    return _pack("tile", rng, pair)


def gen_extend_lines(rng: random.Random) -> Task:
    h, w = rng.randint(8, 13), rng.randint(8, 13)
    color = rng.randint(1, 9)

    def make():
        g = _grid(h, w, 0)
        r = rng.randrange(h)
        c0 = rng.randrange(w - 3)
        n = rng.randint(2, 3)
        for c in range(c0, c0 + n):
            g[r][c] = color
        out = [row[:] for row in g]
        for c in range(c0 + n, w):
            out[r][c] = color
        return g, out

    return _pack("line", rng, [make() for _ in range(4)])


_FAMILIES = [gen_recolor, gen_fill_enclosed, gen_rotate, gen_flip, gen_gravity,
             gen_remove_noise, gen_complete_symmetry, gen_count_bars,
             gen_tile, gen_extend_lines]


def _pack(name: str, rng: random.Random, pairs: List[Tuple[Grid, Grid]]) -> Task:
    tid = f"{name}-{rng.randrange(1 << 24):06x}"
    return {"id": tid,
            "train": [{"input": i, "output": o} for i, o in pairs[:3]],
            "test": [{"input": pairs[3][0], "output": pairs[3][1]}]}


def generate_pack(n: int = 200, seed: int = 1234) -> List[Task]:
    rng = random.Random(seed)
    tasks = []
    for i in range(n):
        fam = _FAMILIES[i % len(_FAMILIES)]
        tasks.append(fam(rng))
    rng.shuffle(tasks)
    return tasks


def write_pack(path: str, tasks: Iterable[Task]) -> None:
    os.makedirs(os.path.dirname(path) or ".", exist_ok=True)
    with open(path, "w", encoding="utf-8") as fh:
        for t in tasks:
            fh.write(json.dumps(t) + "\n")


if __name__ == "__main__":
    import argparse

    ap = argparse.ArgumentParser(description="Generate the local ARC-AGI-2-format pack")
    ap.add_argument("--out", default="data/local_pack")
    ap.add_argument("--n", type=int, default=200)
    args = ap.parse_args()
    os.makedirs(args.out, exist_ok=True)
    write_pack(os.path.join(args.out, "training.jsonl"), generate_pack(args.n, 1234))
    write_pack(os.path.join(args.out, "evaluation.jsonl"), generate_pack(args.n, 5678))
    print(f"Wrote {args.n} tasks per split to {args.out}")
EOF
