"""Example-driven program synthesis for ARC grids.

A task is solved by finding a short program (in a typed DSL of grid
primitives) that maps every training input to its output. Programs are
enumerated bottom-up by increasing cost; the first program consistent with
all training pairs is applied to the test input.

The DSL is *universal* in the sense that it is fixed across all tasks:
nothing about a task is hard-coded, only the learned output of synthesis.
"""
from __future__ import annotations

import itertools
from dataclasses import dataclass
from typing import Callable, Dict, List, Optional, Sequence, Tuple

Grid = List[List[int]]
ROWS = 10
COLS = 10

# --------------------------------------------------------------------------- #
# Grid primitives
# --------------------------------------------------------------------------- #

def _dims(g: Grid):
    return len(g), len(g[0]) if g else 0


def _same(a: Grid, b: Grid) -> bool:
    return a == b


def rot90(g: Grid) -> Grid:
    return [list(row) for row in zip(*g[::-1])]


def rot180(g: Grid) -> Grid:
    return [row[::-1] for row in g[::-1]]


def rot270(g: Grid) -> Grid:
    return [list(row) for row in zip(*g)][::-1]


def flip_h(g: Grid) -> Grid:
    return [row[:] for row in g[::-1]]


def flip_v(g: Grid) -> Grid:
    return [row[::-1] for row in g]


def transpose(g: Grid) -> Grid:
    return [list(row) for row in zip(*g)]


def gravity_down(g: Grid) -> Grid:
    """Compact all non-zero cells down in each column (floor is inferred
    from the bottom row: if the bottom row is uniformly non-zero it acts
    as the floor and stays fixed)."""
    h, w = _dims(g)
    floor_row = h - 1
    has_floor = w > 0 and all(g[h - 1][c] != 0 for c in range(w))
    if has_floor:
        floor_row = h - 2
    out = [[0] * w for _ in range(h)]
    if has_floor:
        out[h - 1] = g[h - 1][:]
    for c in range(w):
        cells = [g[r][c] for r in range(floor_row + 1) if g[r][c] != 0]
        for i, v in enumerate(cells):
            out[floor_row - i][c] = v
    return out


def fill_enclosed(g: Grid) -> Grid:
    """Flood-fill background(0) from the border; interior 0-regions are
    recolored with the most frequent bordering non-zero color."""
    h, w = _dims(g)
    reach = [[False] * w for _ in range(h)]
    stack = [(r, c) for r in (0, h - 1) for c in range(w) if g[r][c] == 0]
    stack += [(r, c) for c in (0, w - 1) for r in range(h) if g[r][c] == 0]
    while stack:
        r, c = stack.pop()
        if not (0 <= r < h and 0 <= c < w) or reach[r][c] or g[r][c] != 0:
            continue
        reach[r][c] = True
        stack += [(r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)]
    out = [row[:] for row in g]
    for r in range(h):
        for c in range(w):
            if g[r][c] == 0 and not reach[r][c]:
                votes: Dict[int, int] = {}
                for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w and g[nr][nc] != 0:
                        votes[nr] = votes.get(nr, 0) + 1
                out[r][c] = max(votes, key=votes.get) if votes else 0
    return out


def remove_non_major(g: Grid) -> Grid:
    """Keep only the most frequent non-background color (denoise)."""
    counts: Dict[int, int] = {}
    for row in g:
        for v in row:
            if v != 0:
                counts[v] = counts.get(v, 0) + 1
    if not counts:
        return [row[:] for row in g]
    keep = max(counts, key=counts.get)
    return [[v if v == keep else 0 for v in row] for row in g]


def complete_sym_h(g: Grid) -> Grid:
    h, w = _dims(g)
    out = [row[:] for row in g]
    for r in range(h):
        for c in range(w // 2):
            v = out[r][c] if out[r][c] != 0 else out[r][w - 1 - c]
            out[r][c] = v
            out[r][w - 1 - c] = v
    return out


def complete_sym_v(g: Grid) -> Grid:
    return flip_h(complete_sym_h(flip_h(g)))


def extend_lines(g: Grid) -> Grid:
    """Extend any horizontal/vertical run of length >=2 to the grid edge."""
    h, w = _dims(g)
    out = [row[:] for row in g]
    for r in range(h):
        for c in range(w - 2):
            if g[r][c] != 0 and g[r][c] == g[r][c + 1] and g[r][c + 1] == g[r][c + 2]:
                for cc in range(c, w):
                    out[r][cc] = g[r][c]
                for cc in range(c + 1):
                    out[r][cc] = g[r][c]
    for c in range(w):
        for r in range(h - 2):
            if g[r][c] != 0 and g[r][c] == g[r + 1][c] and g[r + 1][c] == g[r + 2][c]:
                for rr in range(r, h):
                    out[rr][c] = g[r][c]
                for rr in range(r + 1):
                    out[rr][c] = g[r][c]
    return out


def replace_factory(a: int, b: int) -> Callable[[Grid], Grid]:
    def f(g: Grid) -> Grid:
        return [[b if v == a else v for v in row] for row in g]
    f.__name__ = f"replace_{a}_{b}"
    return f


def mask_color_factory(a: int) -> Callable[[Grid], Grid]:
    def f(g: Grid) -> Grid:
        return [[v if v == a else 0 for v in row] for row in g]
    f.__name__ = f"keep_{a}"
    return f


def gravity_towards(dir_: str) -> Callable[[Grid], Grid]:
    def f(g: Grid):
        if dir_ == "up":
            return flip_h(gravity_down(flip_h(g)))
        if dir_ == "left":
            return transpose(gravity_down(transpose(g)))
        if dir_ == "right":
            t = transpose(g)
            t = flip_h(t)
            t = gravity_down(t)
            t = flip_h(t)
            return transpose(t)
        return gravity_down(g)
    f.__name__ = f"gravity_{dir_}"
    return f


# --------------------------------------------------------------------------- #
# DSL program representation
# --------------------------------------------------------------------------- #

@dataclass(frozen=True)
class Program:
    name: str
    fn: Callable[[Grid], Grid]
    cost: int
    preserves_size: bool

    def __call__(self, g: Grid) -> Grid:
        return self.fn(g)


# Primitive library (unary, composed via function composition)
_PRIMITIVES: List[Program] = []
for nm, fn, cost in [
    ("rot90", rot90, 1), ("rot180", rot180, 1), ("rot270", rot270, 1),
    ("flip_h", flip_h, 1), ("flip_v", flip_v, 1), ("transpose", transpose, 1),
