def rot90(g: Grid) -> Grid:
    return [list(row) for row in zip(*g[::-1])]


def rot180(g: Grid) -> Grid:
    return [row[::-1] for row in g[::-1]]


def rot270(g: Grid) -> Grid:
    return [list(row) for row in zip(*g)][::-1]


def flip_h(g: Grid) -> Grid:
    return [row[:] for row in g[::-1]]


def flip_v(g: Grid) -> Grid:
    return [row[::-1] for row in g]


def transpose(g: Grid) -> Grid:
    return [list(row) for row in zip(*g)]


def gravity_down(g: Grid) -> Grid:
    """Compact non-zero cells down per column; a uniformly non-zero bottom
    row is treated as an immutable floor."""
    h, w = _dims(g)
    has_floor = w > 0 and h > 1 and all(g[h - 1][c] != 0 for c in range(w))
    last = h - 2 if has_floor else h - 1
    out = [[0] * w for _ in range(h)]
    if has_floor:
        out[h - 1] = g[h - 1][:]
    for c in range(w):
        cells = [g[r][c] for r in range(last + 1) if g[r][c] != 0]
        for i, v in enumerate(cells):
            out[last - i][c] = v
    return out


def fill_enclosed(g: Grid) -> Grid:
    """Recolor background(0) regions unreachable from the border with the
    color of their surrounding wall."""
    h, w = _dims(g)
    reach = [[False] * w for _ in range(h)]
    stack = [(r, c) for r in (0, h - 1) for c in range(w) if g[r][c] == 0]
    stack += [(r, c) for c in (0, w - 1) for r in range(1, h - 1) if g[r][c] == 0]
    while stack:
        r, c = stack.pop()
        if not (0 <= r < h and 0 <= c < w) or reach[r][c] or g[r][c] != 0:
            continue
        reach[r][c] = True
        stack += [(r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)]
    out = [row[:] for row in g]
    for r in range(h):
        for c in range(w):
            if g[r][c] == 0 and not reach[r][c]:
                votes: Dict[int, int] = {}
                for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w and g[nr][nc] != 0:
                        votes[nr] = votes.get(nr, 0) + 1
                out[r][c] = max(votes, key=votes.get) if votes else 0
    return out


def remove_non_major(g: Grid) -> Grid:
    """Keep only the most frequent non-background color."""
    counts: Dict[int, int] = {}
    for row in g:
        for v in row:
            if v != 0:
                counts[v] = counts.get(v, 0) + 1
    if not counts:
        return [row[:] for row in g]
    keep = max(counts, key=counts.get)
    return [[v if v == keep else 0 for v in row] for row in g]


def complete_sym_h(g: Grid) -> Grid:
    """Mirror the left half onto the right, OR-ing information from both."""
    h, w = _dims(g)
    out = [row[:] for row in g]
    for r in range(h):
        for c in range(w // 2):
            v = out[r][c] if out[r][c] != 0 else out[r][w - 1 - c]
            out[r][c] = v
            out[r][w - 1 - c] = v
    return out


def complete_sym_v(g: Grid) -> Grid:
    return flip_h(complete_sym_h(flip_h(g)))


def extend_lines(g: Grid) -> Grid:
    """Extend any length-3 horizontal/vertical run to both grid edges."""
    h, w = _dims(g)
    out = [row[:] for row in g]
    for r in range(h):
        c = 0
        while c < w - 2:
            if g[r][c] != 0 and g[r][c] == g[r][c + 1] == g[r][c + 2]:
                col = g[r][c]
                for cc in range(w):
                    out[r][cc] = col
                while c < w - 2 and g[r][c] == col:
                    c += 1
            else:
                c += 1
    for c in range(w):
        r = 0
        while r < h - 2:
            if g[r][c] != 0 and g[r][c] == g[r + 1][c] == g[r + 2][c]:
                col = g[r][c]
                for rr in range(h):
                    out[rr][c] = col
                while r < h - 2 and g[r][c] == col:
                    r += 1
            else:
                r += 1
    return out


def replace_factory(a: int, b: int) -> Callable[[Grid], Grid]:
    def f(g: Grid) -> Grid:
        return [[b if v == a else v for v in row] for row in g]
    f.__name__ = f"replace_{a}_{b}"
    return f


def mask_color_factory(a: int) -> Callable[[Grid], Grid]:
    def f(g: Grid) -> Grid:
        return [[v if v == a else 0 for v in row] for row in g]
    f.__name__ = f"keep_{a}"
    return f


def gravity_towards(dir_: str) -> Callable[[Grid], Grid]:
    def f(g: Grid):
        if dir_ == "up":
            return flip_h(gravity_down(flip_h(g)))
        if dir_ == "left":
            return transpose(gravity_down(transpose(g)))
        if dir_ == "right":
            t = flip_v(transpose(g))
            return transpose(flip_v(gravity_down(t)))
        return gravity_down(g)
    f.__name__ = f"gravity_{dir_}"
    return f


# --------------------------------------------------------------------------- #
# DSL
# --------------------------------------------------------------------------- #

@dataclass(frozen=True)
class Program:
    name: str
    fn: Callable[[Grid], Grid]
    cost: int

    def __call__(self, g: Grid) -> Grid:
        return self.fn(g)


