    out = [row[:] for row in g]
    for r in range(h):
        c = 0
        while c < w - 2:
            if g[r][c] != 0 and g[r][c] == g[r][c + 1] == g[r][c + 2]:
                col = g[r][c]
                for cc in range(w):
                    out[r][cc] = col
                while c < w - 2 and g[r][c] == col:
                    c += 1
            else:
                c += 1
    for c in range(w):
        r = 0
        while r < h - 2:
            if g[r][c] != 0 and g[r][c] == g[r + 1][c] == g[r + 2][c]:
                col = g[r][c]
                for rr in range(h):
                    out[rr][c] = col
                while r < h - 2 and g[r][c] == col:
                    r += 1
            else:
                r += 1
    return out


def replace_factory(a: int, b: int) -> Callable[[Grid], Grid]:
    def f(g: Grid) -> Grid:
        return [[b if v == a else v for v in row] for row in g]
    f.__name__ = f"replace_{a}_{b}"
    return f


def mask_color_factory(a: int) -> Callable[[Grid], Grid]:
    def f(g: Grid) -> Grid:
        return [[v if v == a else 0 for v in row] for row in g]
    f.__name__ = f"keep_{a}"
    return f


def gravity_towards(dir_: str) -> Callable[[Grid], Grid]:
    def f(g: Grid):
        if dir_ == "up":
            return flip_h(gravity_down(flip_h(g)))
        if dir_ == "left":
            return transpose(gravity_down(transpose(g)))
        if dir_ == "right":
            t = flip_v(transpose(g))
            return transpose(flip_v(gravity_down(t)))
        return gravity_down(g)
    f.__name__ = f"gravity_{dir_}"
    return f


