@dataclass(frozen=True)
class Program:
    name: str
    fn: Callable[[Grid], Grid]
    cost: int

    def __call__(self, g: Grid) -> Grid:
        return self.fn(g)


_PRIMITIVES: List[Program] = []
for nm, fn, cost in [
    ("rot90", rot90, 1), ("rot180", rot180, 1), ("rot270", rot270, 1),
    ("flip_h", flip_h, 1), ("flip_v", flip_v, 1), ("transpose", transpose, 1),
    ("gravity_down", gravity_down, 2), ("gravity_up", gravity_towards("up"), 2),
    ("gravity_left", gravity_towards("left"), 2),
    ("gravity_right", gravity_towards("right"), 2),
    ("fill_enclosed", fill_enclosed, 3),
    ("remove_non_major", remove_non_major, 2),
    ("complete_sym_h", complete_sym_h, 2),
    ("complete_sym_v", complete_sym_v, 2),
    ("extend_lines", extend_lines, 2),
]:
    _PRIMITIVES.append(Program(nm, fn, cost))

for a in range(10):
    for b in range(10):
        if a != b:
            _PRIMITIVES.append(Program(f"replace_{a}->{b}", replace_factory(a, b), 1))
for a in range(1, 10):
    _PRIMITIVES.append(Program(f"keep_{a}", mask_color_factory(a), 1))

_IDENTITY = Program("identity", lambda g: [row[:] for row in g], 0)


@dataclass
class SynthesisResult:
    program: Optional[Program]
    name: str
    cost: int
    n_candidates: int


def _compose(outer: Program, inner: Program) -> Program:
    return Program(
        f"{outer.name} o {inner.name}",
        lambda g: outer.fn(inner.fn(g)),
        outer.cost + inner.cost,
    )


def _check(p: Program, pairs) -> bool:
    for src, dst in pairs:
        try:
            pred = p(src)
        except Exception:
            return False
        if pred != dst:
            return False
    return True


def synthesize_task(task: dict, max_cost: int = 5,
                    max_nodes: int = 6000) -> SynthesisResult:
    """Cheapest-first enumeration of compositions consistent with train pairs."""
    pairs = [(p["input"], p["output"]) for p in task["train"]]

    if _check(_IDENTITY, pairs):
        return SynthesisResult(_IDENTITY, _IDENTITY.name, 0, 0)

    by_cost = sorted(_PRIMITIVES, key=lambda p: (p.cost, p.name))
    # frontier[c] = programs of cost c that are still live candidates
    frontier: Dict[int, List[Program]] = {0: [_IDENTITY]}
    seen = {_IDENTITY.name}
    tested = 1

    for budget in range(1, max_cost + 1):
        layer: List[Program] = []
        for c, progs in frontier.items():
            for inner in progs:
                for prim in by_cost:
                    cost = c + prim.cost
                    if cost != budget:
                        continue
                    cand = _compose(prim, inner)
                    if cand.name in seen:
                        continue
                    seen.add(cand.name)
                    tested += 1
                    if _check(cand, pairs):
                        return SynthesisResult(cand, cand.name, cand.cost, tested)
                    layer.append(cand)
                    if tested >= max_nodes:
                        return SynthesisResult(None, "no_solution", max_cost + 1, tested)
        if layer:
            frontier[budget] = layer
    return SynthesisResult(None, "no_solution", max_cost + 1, tested)


def predict(task: dict, max_cost: int = 5,
            max_nodes: int = 6000) -> Tuple[Optional[Grid], SynthesisResult]:
    res = synthesize_task(task, max_cost=max_cost, max_nodes=max_nodes)
    if res.program is None:
        return None, res
    try:
        return res.program(task["test"][0]["input"]), res
    except Exception:
        return None, res
