"""Smoke tests: determinism, DSL correctness, schema, coverage floor."""
import json
from solver.data import generate_pack
from solver.synthesize import predict
from solver.evaluate import evaluate
from solver.predict_submit import make_predictions


def test_determinism():
    a = generate_pack(50, 7)
    b = generate_pack(50, 7)
    assert a == b


def test_primitives_fit_and_generalize():
    tasks = generate_pack(200, 5678)
    hits = 0
    for t in tasks:
        pred, res = predict(t)
        # returned program must always reproduce training exactly
        if res.program is not None:
